// tb_scheduler_heldout_correctness.sv
//
// Phase 14: correctness check for the 9 HELD-OUT scheduler workloads
// (sim/programs/scheduler/*_n{2,3,8,32}.s for vecadd/dot,
// *_matmul_n1.s), generated by the same
// scheduler/benchmarks/gen_scheduler_programs.py used in Phase 13 but
// deliberately never included in scheduler/training/dataset.csv (see
// that script's HELDOUT_* size lists and their header comment). These
// sizes exist purely so scheduler/inference/evaluate_accuracy.py can
// score the trained model's predictions against real simulated ground
// truth it never fit on -- vecadd/dot N=2 and N=3 sit exactly inside
// the "real crossover point is unknown" gap documented in
// docs/scheduler.md, N=8/N=32 test extrapolation further out, and
// matmul N=1 (a degenerate 1x1 case) is the only remaining valid
// matmul size the power-of-two/MAX_DIM=8 constraint allows.
//
// Same "verify correctness before trusting timing" discipline as
// every prior benchmarking phase, and the same multi-DUT pattern as
// sim/testbenches/tb_scheduler_correctness.sv (Phase 13). Expected
// values computed in Python, not by hand:
//
//   python3 -c "
//   def vecadd(n): return [2*i+3 for i in range(n)]
//   def dot(n): return sum((i+1)*(i+2) for i in range(n))
//   def matmul(n):
//       A=[[i+j+1 for j in range(n)] for i in range(n)]
//       B=[[i+j+2 for j in range(n)] for i in range(n)]
//       return [sum(A[i][k]*B[k][j] for k in range(n))
//               for i in range(n) for j in range(n)]
//   for n in [2,3,8,32]:
//       print(n, vecadd(n)[0], vecadd(n)[-1], dot(n))
//   print(matmul(1))
//   "

`timescale 1ns/1ps

module tb_scheduler_heldout_correctness;

  logic clk;
  logic rst_n = 0;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  int errors = 0;

  task automatic check(string name, logic [31:0] actual, logic [31:0] expected);
    if (actual !== expected) begin
      $display("  [FAIL] %-28s expected=%0d actual=%0d", name, expected, actual);
      errors++;
    end else begin
      $display("  [PASS] %-28s = %0d", name, actual);
    end
  endtask

  task automatic check_sentinel(string name, logic [31:0] gpio_out);
    check({name, " sentinel"}, gpio_out, 32'hDEADBEEF);
  endtask

  `define SOC_PORTS(gpio_out_sig) \
    .clk(clk), .rst_n(rst_n), .gpio_in(32'b0), .gpio_out(gpio_out_sig), \
    .uart_tx_valid(), .uart_tx_byte(), \
    .dbg_if_pc(), .dbg_if_instr(), .dbg_id_pc(), .dbg_id_instr(), \
    .dbg_ex_pc(), .dbg_ex_instr(), .dbg_mem_instr(), .dbg_wb_instr(), \
    .dbg_reg_write(), .dbg_rd_addr(), .dbg_rd_data(), \
    .dbg_illegal(), .dbg_stall(), .dbg_flush(), \
    .perf_cycle_count(), .perf_instr_retired_count(), .perf_stall_count(), \
    .perf_branch_count(), .perf_branch_taken_count(), .perf_load_use_stall_count(), \
    .perf_forwarding_event_count(), .perf_flush_count()

  // -------------------------------------------------------------------
  // CPU-only instances
  // -------------------------------------------------------------------
  logic [31:0] cpu_va2_gpio, cpu_va3_gpio, cpu_va8_gpio, cpu_va32_gpio;
  logic [31:0] cpu_dot2_gpio, cpu_dot3_gpio, cpu_dot8_gpio, cpu_dot32_gpio;
  logic [31:0] cpu_mm1_gpio;

  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_vecadd_n2.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_va2 (`SOC_PORTS(cpu_va2_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_vecadd_n3.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_va3 (`SOC_PORTS(cpu_va3_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_vecadd_n8.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_va8 (`SOC_PORTS(cpu_va8_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_vecadd_n32.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_va32 (`SOC_PORTS(cpu_va32_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_n2.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_dot2 (`SOC_PORTS(cpu_dot2_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_n3.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_dot3 (`SOC_PORTS(cpu_dot3_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_n8.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_dot8 (`SOC_PORTS(cpu_dot8_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_dot_n32.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_dot32 (`SOC_PORTS(cpu_dot32_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/cpu_matmul_n1.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu_mm1 (`SOC_PORTS(cpu_mm1_gpio));

  // -------------------------------------------------------------------
  // Accelerator-driven instances
  // -------------------------------------------------------------------
  logic [31:0] acc_va2_gpio, acc_va3_gpio, acc_va8_gpio, acc_va32_gpio;
  logic [31:0] acc_dot2_gpio, acc_dot3_gpio, acc_dot8_gpio, acc_dot32_gpio;
  logic [31:0] acc_mm1_gpio;

  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_vecadd_n2.hex"))
    dut_acc_va2 (`SOC_PORTS(acc_va2_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_vecadd_n3.hex"))
    dut_acc_va3 (`SOC_PORTS(acc_va3_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_vecadd_n8.hex"))
    dut_acc_va8 (`SOC_PORTS(acc_va8_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_vecadd_n32.hex"))
    dut_acc_va32 (`SOC_PORTS(acc_va32_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_dot_n2.hex"))
    dut_acc_dot2 (`SOC_PORTS(acc_dot2_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_dot_n3.hex"))
    dut_acc_dot3 (`SOC_PORTS(acc_dot3_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_dot_n8.hex"))
    dut_acc_dot8 (`SOC_PORTS(acc_dot8_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_dot_n32.hex"))
    dut_acc_dot32 (`SOC_PORTS(acc_dot32_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/accel_matmul_n1.hex"))
    dut_acc_mm1 (`SOC_PORTS(acc_mm1_gpio));

  localparam int MAX_CYCLES = 40000; // largest here (dot/vecadd N=32) is far
                                      // cheaper than Phase 13's cpu_matmul_n8;
                                      // kept generous rather than tuned tight.

  initial begin
    $display("=== Phase 14 held-out scheduler-workload correctness check ===");

    rst_n = 0;
    repeat (2) @(posedge clk);
    #1;
    rst_n = 1;

    repeat (MAX_CYCLES) @(posedge clk);
    #1;

    // ---- CPU-only: vecadd N=2, N=3 (inside the unexplored crossover gap) ----
    $display("");
    $display("--- cpu_vecadd N=2, N=3 ---");
    check_sentinel("cpu_vecadd_n2", cpu_va2_gpio);
    check("va2 out[0]", dut_cpu_va2.ram_inst.mem[16'h0C00+0], 32'd3);
    check("va2 out[1]", dut_cpu_va2.ram_inst.mem[16'h0C00+1], 32'd5);
    check_sentinel("cpu_vecadd_n3", cpu_va3_gpio);
    check("va3 out[0]", dut_cpu_va3.ram_inst.mem[16'h0C00+0], 32'd3);
    check("va3 out[2]", dut_cpu_va3.ram_inst.mem[16'h0C00+2], 32'd7);

    // ---- CPU-only: vecadd N=8, N=32 ----
    $display("");
    $display("--- cpu_vecadd N=8, N=32 ---");
    check_sentinel("cpu_vecadd_n8", cpu_va8_gpio);
    check("va8 out[0]", dut_cpu_va8.ram_inst.mem[16'h0C00+0], 32'd3);
    check("va8 out[7]", dut_cpu_va8.ram_inst.mem[16'h0C00+7], 32'd17);
    check_sentinel("cpu_vecadd_n32", cpu_va32_gpio);
    check("va32 out[0]",  dut_cpu_va32.ram_inst.mem[16'h0C00+0],  32'd3);
    check("va32 out[31]", dut_cpu_va32.ram_inst.mem[16'h0C00+31], 32'd65);

    // ---- CPU-only: dot N=2, N=3, N=8, N=32 ----
    $display("");
    $display("--- cpu_dot N=2, N=3, N=8, N=32 ---");
    check_sentinel("cpu_dot_n2", cpu_dot2_gpio);
    check("dot2 (x20)", dut_cpu_dot2.cpu_inst.regfile_inst.regs[20], 32'd8);
    check_sentinel("cpu_dot_n3", cpu_dot3_gpio);
    check("dot3 (x20)", dut_cpu_dot3.cpu_inst.regfile_inst.regs[20], 32'd20);
    check_sentinel("cpu_dot_n8", cpu_dot8_gpio);
    check("dot8 (x20)", dut_cpu_dot8.cpu_inst.regfile_inst.regs[20], 32'd240);
    check_sentinel("cpu_dot_n32", cpu_dot32_gpio);
    check("dot32 (x20)", dut_cpu_dot32.cpu_inst.regfile_inst.regs[20], 32'd11968);

    // ---- CPU-only: matmul N=1 (degenerate 1x1) ----
    $display("");
    $display("--- cpu_matmul N=1 ---");
    check_sentinel("cpu_matmul_n1", cpu_mm1_gpio);
    check("C[0]", dut_cpu_mm1.ram_inst.mem[16'h0C00+0], 32'd2);

    // ---- Accelerator-driven: vecadd N=2, N=3 ----
    $display("");
    $display("--- accel_vecadd N=2, N=3 ---");
    check_sentinel("accel_vecadd_n2", acc_va2_gpio);
    check("va2 vecout[0]", dut_acc_va2.accel_inst.vecout[0], 32'd3);
    check("va2 vecout[1]", dut_acc_va2.accel_inst.vecout[1], 32'd5);
    check_sentinel("accel_vecadd_n3", acc_va3_gpio);
    check("va3 vecout[0]", dut_acc_va3.accel_inst.vecout[0], 32'd3);
    check("va3 vecout[2]", dut_acc_va3.accel_inst.vecout[2], 32'd7);

    // ---- Accelerator-driven: vecadd N=8, N=32 ----
    $display("");
    $display("--- accel_vecadd N=8, N=32 ---");
    check_sentinel("accel_vecadd_n8", acc_va8_gpio);
    check("va8 vecout[0]", dut_acc_va8.accel_inst.vecout[0], 32'd3);
    check("va8 vecout[7]", dut_acc_va8.accel_inst.vecout[7], 32'd17);
    check_sentinel("accel_vecadd_n32", acc_va32_gpio);
    check("va32 vecout[0]",  dut_acc_va32.accel_inst.vecout[0],  32'd3);
    check("va32 vecout[31]", dut_acc_va32.accel_inst.vecout[31], 32'd65);

    // ---- Accelerator-driven: dot N=2, N=3, N=8, N=32 ----
    $display("");
    $display("--- accel_dot N=2, N=3, N=8, N=32 ---");
    check_sentinel("accel_dot_n2", acc_dot2_gpio);
    check("dot2 result_r", dut_acc_dot2.accel_inst.result_r, 32'd8);
    check_sentinel("accel_dot_n3", acc_dot3_gpio);
    check("dot3 result_r", dut_acc_dot3.accel_inst.result_r, 32'd20);
    check_sentinel("accel_dot_n8", acc_dot8_gpio);
    check("dot8 result_r", dut_acc_dot8.accel_inst.result_r, 32'd240);
    check_sentinel("accel_dot_n32", acc_dot32_gpio);
    check("dot32 result_r", dut_acc_dot32.accel_inst.result_r, 32'd11968);

    // ---- Accelerator-driven: matmul N=1 (degenerate 1x1) ----
    $display("");
    $display("--- accel_matmul N=1 ---");
    check_sentinel("accel_matmul_n1", acc_mm1_gpio);
    check("mm1 vecout[0]", dut_acc_mm1.accel_inst.vecout[0], 32'd2);

    $display("");
    if (errors == 0) begin
      $display("RESULT: ALL CHECKS PASSED");
    end else begin
      $display("RESULT: %0d CHECK(S) FAILED", errors);
    end
    $finish;
  end

endmodule
